export default function incidentRequest({ from, serviceId, title, updatedTitle }) {
  if (
    typeof from !== "string" ||
    !from ||
    typeof serviceId !== "string" ||
    !serviceId ||
    typeof title !== "string" ||
    !title ||
    typeof updatedTitle !== "string" ||
    !updatedTitle
  )
    throw new Error("Configure the PagerDuty member email, service ID and both titles");
  return {
    endpoint: "/incidents",
    headers: { From: from },
    body: {
      incident: { type: "incident", title, service: { id: serviceId, type: "service_reference" } },
    },
    updatedTitle,
  };
}

