export default function createdIncident({ body, statusCode, bodyEncoding, updatedTitle }) {
  if (statusCode !== 201)
    throw new Error("PagerDuty did not confirm incident creation with HTTP 201");
  const incidentId = body?.incident?.id;
  if (bodyEncoding != null || typeof incidentId !== "string" || !incidentId)
    throw new Error("PagerDuty creation response has no incident ID");
  if (typeof updatedTitle !== "string" || !updatedTitle)
    throw new Error("Configure the updated incident title");
  return { incidentId, update: { type: "incident", title: updatedTitle } };
}

