export default function incidentId({ incident, expectedId }) {
  if (!incident || typeof incident.id !== "string" || !incident.id || incident.id !== expectedId)
    throw new Error("PagerDuty returned a different or missing incident ID");
  return { incident, incidentId: incident.id };
}

